    return jsonify({
        'answer_vi': 'Đang xây dựng vector index. Vui lòng quay lại sau.',
        'citations': [], 'entity_id': entity_id
    })

function sendChat() {
  var input = document.getElementById('da-chat-input');
  var log = document.getElementById('da-chat-log');
  var q = input.value.trim(); if (!q) return;
  log.innerHTML += '<div style="color:var(--da-gold);font-size:11px">Bạn: ' + q + '</div>';
  input.value = '';
  fetch('/daoanh/api/rag_vi/chat', { method: 'POST',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({question: q, entity_id: window._currentEntityId || ''})
  }).then(r => r.json()).then(d => {
    log.innerHTML += '<div style="font-size:11px;margin-bottom:8px">' + (d.answer_vi || d.error) + '</div>';
    log.scrollTop = log.scrollHeight;
  });
}

