@app.route('/daoanh/api/places/<place_id>/bdrc')
def api_place_bdrc(place_id):
    try:
        conn = get_db()
        row = conn.execute("""
            SELECT esi.source_entity_id AS bdrc_id,
                   esi.confidence, esi.match_status
            FROM entity_source_ids esi
            JOIN places_dila pd ON pd.id = esi.entity_id
            WHERE pd.place_id = ? AND esi.source = 'BDRC'
            ORDER BY esi.confidence DESC LIMIT 1
        """, [place_id]).fetchone()
        if not row:
            return jsonify({'ok': False, 'bdrc_id': None,
                            'note': 'No BDRC mapping for this place'}), 200
        from adapters.bdrc.bdrc_adapter import fetch_entity
        bdrc_data = fetch_entity(row['bdrc_id']) or {}
        return jsonify({'ok': True, 'bdrc_id': row['bdrc_id'],
                        'match_status': row['match_status'],
                        'confidence': row['confidence'],
                        'bdrc': bdrc_data})
    except Exception as e:
        app.logger.error(f'api_place_bdrc error: {e}')
        return jsonify({'ok': False, 'error': str(e)}), 500

